import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int[] input = parseInput(scanner);
        int n = input[0];
        int mod = input[1];

        int[] dpArray = new int[n + 1];
        long totalValue = 1;
        dpArray[1] = 1;

        for (int i = 2; i <= n; i++) {
            int limit = (int) Math.sqrt(i) + 1;
            long currentSum = totalValue;

            for (int f = 2; f < limit; f++) {
                currentSum = (currentSum + dpArray[i / f]) % mod;
            }

            int endPoint = i;
            for (int j = 1; j <= i / limit; j++) {
                int nextPoint = i / (j + 1);
                currentSum = (currentSum + (long)(endPoint - nextPoint) * dpArray[j]) % mod;
                endPoint = nextPoint;
            }

            totalValue = (totalValue + currentSum) % mod;
            dpArray[i] = (int) currentSum;
        }

        System.out.println(dpArray[n]);
        scanner.close();
    }

    private static int[] parseInput(Scanner scanner) {
        String[] parts = scanner.nextLine().split(" ");
        int[] result = new int[parts.length];
        for (int i = 0; i < parts.length; i++) {
            result[i] = Integer.parseInt(parts[i]);
        }
        return result;
    }
}
